// getTestExternalConnectorSiteEndpoint returns the referenced CE site endpoint for acceptance tests.
//
// Why: External connector creation validates the tunnel endpoint against the referenced CE site, so
// the test must use a real site name with a node and interface that belong to that site.
//
// How: It reads F5XC_TEST_SITE, F5XC_TEST_SITE_NODE, and F5XC_TEST_SITE_INTERFACE when they are set,
// otherwise it falls back to the shared OCI CE site and network-interface object used by the
// acceptance environment.
//
// Parameters:
//   - t: test handle used for logging the selected endpoint.
//
// Returns:
//   - string: CE site name used in ce_site_reference.
//   - string: CE node name used in tunnel_eps.node.
//   - string: CE network-interface object name used in tunnel_eps.interface.
//
// Example:
//
//	siteName, siteNode, siteInterface := getTestExternalConnectorSiteEndpoint(t)
func getTestExternalConnectorSiteEndpoint(t *testing.T) (string, string, string) {
	siteName := "agam-oci-single-node"
	if site := os.Getenv("F5XC_TEST_SITE"); site != "" {
		siteName = site
	}

	siteNode := "agam-oci-single-node-crt"
	if node := os.Getenv("F5XC_TEST_SITE_NODE"); node != "" {
		siteNode = node
	}

	siteInterface := "ves-io-securemesh-site-v2-agam-oci-single-node-network-agam-oci-single-node-crt-enp0s5-0"
	if iface := os.Getenv("F5XC_TEST_SITE_INTERFACE"); iface != "" {
		siteInterface = iface
	}

	t.Logf("Using CE site endpoint for external connector acceptance test: site=%s node=%s interface=%s", siteName, siteNode, siteInterface)
	return siteName, siteNode, siteInterface
}

